function detectLang() {
    const lang = (navigator.languages?.[0] ?? navigator.language).toLowerCase();
    return lang === "ja" || lang === "ja-jp" ? "ja" : "en";
}
function detectMacOS() {
    // biome-ignore lint/complexity/useLiteralKeys: userAgentData is not in TS lib types
    const uad = navigator["userAgentData"];
    if (uad?.platform) {
        return uad.platform === "macOS";
    }
    return /mac/i.test(navigator.platform);
}
const KEY_LABELS = {
    altKey: { en: "alt", ja: "Alt" },
    ctrlKey: { en: "Ctrl", ja: "Ctrl" },
    metaKey: { en: "⌘", ja: "⌘" },
};
const MESSAGES = {
    en: (key) => ({
        wheel: `Use ${KEY_LABELS[key].en} + scroll to zoom the map.`,
        touch: "Use two fingers to move the map.",
    }),
    ja: (key) => ({
        wheel: `${KEY_LABELS[key].ja} キーを押しながらスクロールしてください。`,
        touch: "2本指を使って操作してください。",
    }),
};
function resolveModifierKey(option) {
    switch (option) {
        case "alt":
            return "altKey";
        case "ctrl":
            return "ctrlKey";
        case "meta":
            return "metaKey";
        default:
            // "auto" or undefined
            return detectMacOS() ? "metaKey" : "ctrlKey";
    }
}
function resolveSettings(options) {
    const modifierKey = resolveModifierKey(options.modifierKey);
    const lang = options.lang === "auto" || !options.lang ? detectLang() : options.lang;
    const messages = MESSAGES[lang](modifierKey);
    return {
        backgroundColor: options.backgroundColor ?? "rgba(0, 0, 0, 0.8)",
        textColor: options.textColor ?? "#ffffff",
        textMessage: options.textMessage ?? messages.wheel,
        textMessageMobile: options.textMessageMobile ?? messages.touch,
        timeout: options.timeout ?? 2000,
        modifierKey,
    };
}
export class GestureHandling {
    constructor(options = {}) {
        this.fullscreen = false;
        this.timer = null;
        this.settings = resolveSettings(options);
        this.handleWheel = this.onWheel.bind(this);
        this.handleHelpWheel = this.onHelpWheel.bind(this);
        this.handleHelpTouchStart = this.onHelpTouchStart.bind(this);
        this.handleMoveStart = this.onMoveStart.bind(this);
        this.handleFullscreenChange = this.onFullscreenChange.bind(this);
    }
    onAdd(map) {
        this.map = map;
        // ヘルプオーバーレイの作成
        const helpElement = document.createElement("div");
        helpElement.className = "gesture-handling-help-overlay";
        helpElement.style.backgroundColor = this.settings.backgroundColor;
        helpElement.style.position = "absolute";
        helpElement.style.display = "none";
        helpElement.style.zIndex = "9999";
        helpElement.style.justifyContent = "center";
        helpElement.style.alignItems = "center";
        const textBox = document.createElement("div");
        textBox.style.textAlign = "center";
        textBox.style.color = this.settings.textColor;
        helpElement.appendChild(textBox);
        this.helpElement = helpElement;
        // scroll zoom を無効化
        map.scrollZoom.disable();
        // イベントリスナーの登録
        helpElement.addEventListener("wheel", this.handleHelpWheel);
        helpElement.addEventListener("touchstart", this.handleHelpTouchStart, {
            passive: false,
        });
        map.getContainer().addEventListener("wheel", this.handleWheel);
        map.on("movestart", this.handleMoveStart);
        document.addEventListener("fullscreenchange", this.handleFullscreenChange);
        // IControl の要件として空の container を返す
        const container = document.createElement("div");
        container.className = "maplibregl-ctrl";
        container.style.display = "none";
        return container;
    }
    onRemove() {
        this.clearTimer();
        if (this.helpElement) {
            this.helpElement.removeEventListener("wheel", this.handleHelpWheel);
            this.helpElement.removeEventListener("touchstart", this.handleHelpTouchStart);
            this.hideHelp();
            this.helpElement = undefined;
        }
        if (this.map) {
            this.map.getContainer().removeEventListener("wheel", this.handleWheel);
            this.map.off("movestart", this.handleMoveStart);
            this.map.scrollZoom.enable();
            this.map = undefined;
        }
        document.removeEventListener("fullscreenchange", this.handleFullscreenChange);
    }
    getDefaultPosition() {
        return "top-left";
    }
    // --- internal ---
    showHelp(message) {
        const map = this.map;
        const help = this.helpElement;
        if (!map || !help)
            return;
        help.style.top = "0";
        help.style.left = "0";
        help.style.width = "100%";
        help.style.height = "100%";
        help.style.display = "flex";
        const textBox = help.firstElementChild;
        if (textBox) {
            textBox.innerText = message;
        }
        map.getContainer().appendChild(help);
    }
    hideHelp() {
        const help = this.helpElement;
        if (!help)
            return;
        help.style.display = "none";
        help.remove();
    }
    clearTimer() {
        if (this.timer !== null) {
            clearTimeout(this.timer);
            this.timer = null;
        }
    }
    onWheel(event) {
        const map = this.map;
        if (!map)
            return;
        if (event[this.settings.modifierKey] || this.fullscreen) {
            event.preventDefault();
            if (!map.scrollZoom.isEnabled()) {
                map.scrollZoom.reset();
                map.scrollZoom.enable();
            }
        }
        else {
            map.scrollZoom.disable();
            this.showHelp(this.settings.textMessage);
            this.clearTimer();
            this.timer = setTimeout(() => {
                this.hideHelp();
            }, this.settings.timeout);
        }
    }
    onHelpWheel(event) {
        if (event[this.settings.modifierKey] || this.fullscreen) {
            event.preventDefault();
            this.clearTimer();
            this.hideHelp();
        }
        else {
            this.clearTimer();
            this.timer = setTimeout(() => {
                this.hideHelp();
            }, this.settings.timeout);
        }
    }
    onHelpTouchStart(event) {
        const map = this.map;
        if (!map)
            return;
        if (event.touches && (event.touches.length >= 2 || this.fullscreen)) {
            this.clearTimer();
            this.hideHelp();
            map.dragPan.enable();
            event.preventDefault();
        }
    }
    onMoveStart(event) {
        const map = this.map;
        if (!map)
            return;
        if (event.originalEvent &&
            "touches" in event.originalEvent &&
            event.originalEvent.touches.length < 2 &&
            !this.fullscreen) {
            this.showHelp(this.settings.textMessageMobile);
            map.dragPan.disable();
            this.clearTimer();
            this.timer = setTimeout(() => {
                map.dragPan.enable();
                this.hideHelp();
            }, this.settings.timeout);
        }
    }
    onFullscreenChange() {
        this.fullscreen = !!document.fullscreenElement;
    }
}
export default GestureHandling;
